package com.projexa.coaching.academics.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="batches") public class Batch { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false) private UUID academicYearId; @Column(nullable=false) private UUID classId; private UUID streamId; @Column(nullable=false) private String name; private String code; private Integer capacity; private String status="ACTIVE"; public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public void setTenantId(UUID v){tenantId=v;} public UUID getAcademicYearId(){return academicYearId;} public void setAcademicYearId(UUID v){academicYearId=v;} public UUID getClassId(){return classId;} public void setClassId(UUID v){classId=v;} public UUID getStreamId(){return streamId;} public void setStreamId(UUID v){streamId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public Integer getCapacity(){return capacity;} public void setCapacity(Integer v){capacity=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }